// DecodeListManagedDevicesRequest returns a decoder for requests sent to the
// deviceIntegrations listManagedDevices endpoint.
func DecodeListManagedDevicesRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*deviceintegrations.ListManagedDevicesPayload, error) {
	return func(r *http.Request) (*deviceintegrations.ListManagedDevicesPayload, error) {
		var payload *deviceintegrations.ListManagedDevicesPayload
		var (
			provider       *string
			coverageBucket *string
			userIds        []string
			userEmails     []string
			cursor         *string
			limit          int
			apikeyToken    *string
			sessionToken   *string
			err            error
		)
		qp := r.URL.Query()
		providerRaw := qp.Get("provider")
		if providerRaw != "" {
			provider = &providerRaw
		}
		coverageBucketRaw := qp.Get("coverage_bucket")
		if coverageBucketRaw != "" {
			coverageBucket = &coverageBucketRaw
		}
		if coverageBucket != nil {
			if !(*coverageBucket == "agent_active" || *coverageBucket == "agent_stale" || *coverageBucket == "agent_other_device" || *coverageBucket == "no_agent" || *coverageBucket == "no_email" || *coverageBucket == "unresolved_email" || *coverageBucket == "missing") {
				err = goa.MergeErrors(err, goa.InvalidEnumValueError("coverage_bucket", *coverageBucket, []any{"agent_active", "agent_stale", "agent_other_device", "no_agent", "no_email", "unresolved_email", "missing"}))
			}
		}
		userIds = qp["user_ids"]
		userEmails = qp["user_emails"]
		cursorRaw := qp.Get("cursor")
		if cursorRaw != "" {
			cursor = &cursorRaw
		}
		{
			limitRaw := qp.Get("limit")
			if limitRaw == "" {
				limit = 50
			} else {
				v, err2 := strconv.ParseInt(limitRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("limit", limitRaw, "integer"))
				}
				limit = int(v)
			}
		}
		if limit < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 1, true))
		}
		if limit > 200 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("limit", limit, 200, false))
		}
		apikeyTokenRaw := r.Header.Get("Gram-Key")
		if apikeyTokenRaw != "" {
			apikeyToken = &apikeyTokenRaw
		}
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewListManagedDevicesPayload(provider, coverageBucket, userIds, userEmails, cursor, limit, apikeyToken, sessionToken)
		if payload.ApikeyToken != nil {
			if strings.Contains(*payload.ApikeyToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.ApikeyToken, " ", 2)[1]
				payload.ApikeyToken = &cred
			}
		}
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

